import type { IrSchema } from "@varavel/vdl-plugin-sdk";
import type { GeneratorOptions } from "../options/resolve";
import type { PolicyModel } from "../policy/policy-model";
import { exprUsesSlices, renderGoExpr } from "./render-go-expr";

/**
 * Renders the consolidated Go output file for all collected policies.
 */
export function renderGoFile(
  schema: IrSchema,
  policies: PolicyModel[],
  options: GeneratorOptions,
): string {
  const typesPrefix = options.typesImport.length > 0 ? "vdltypes." : "";
  const ctx = { schema, typesPrefix };
  const lines: string[] = [
    "// Generated by VDL. Do not edit.",
    `package ${options.packageName}`,
    "",
  ];

  const needsSlices = policies.some(
    (policy) =>
      exprUsesSlices(policy.allow) ||
      (policy.deny !== undefined && exprUsesSlices(policy.deny)),
  );
  const needsTypesImport =
    options.typesImport.length > 0 && policies.length > 0;
  if (needsSlices || needsTypesImport) {
    lines.push("import (");
    if (needsSlices) {
      lines.push('\t"slices"');
    }
    if (needsTypesImport) {
      lines.push(`\tvdltypes ${JSON.stringify(options.typesImport)}`);
    }
    lines.push(")", "");
  }

  for (const [index, policy] of policies.entries()) {
    lines.push(...renderPolicyFunc(policy, typesPrefix, ctx.schema));
    if (index < policies.length - 1) {
      lines.push("");
    }
  }

  if (policies.length > 0) {
    lines.push("");
    lines.push(...renderCatalog(policies, typesPrefix, ctx.schema));
  }

  return `${lines.join("\n")}\n`;
}

/**
 * Renders one exported policy check function.
 */
function renderPolicyFunc(
  policy: PolicyModel,
  typesPrefix: string,
  schema: IrSchema,
): string[] {
  const params = renderParams(policy, typesPrefix);
  const ctx = { schema, typesPrefix };
  const allowGo = renderGoExpr(policy.allow, ctx);
  const lines: string[] = [];
  lines.push(...renderDocLines(policy));
  lines.push(`func ${policy.goName}(${params}) bool {`);
  if (policy.deny !== undefined) {
    const denyGo = renderGoExpr(policy.deny, ctx);
    lines.push(`\tif ${denyGo} {`);
    lines.push("\t\treturn false");
    lines.push("\t}");
  }
  lines.push(`\treturn ${allowGo}`);
  lines.push("}");
  return lines;
}

/**
 * Renders the parameter list for a policy function in root order.
 */
function renderParams(policy: PolicyModel, typesPrefix: string): string {
  const parts = [`principal ${typesPrefix}${policy.principalGoName}`];
  if (
    policy.resourceType !== undefined &&
    policy.resourceGoName !== undefined
  ) {
    parts.push(`resource ${typesPrefix}${policy.resourceGoName}`);
  }
  if (policy.contextType !== undefined && policy.contextGoName !== undefined) {
    parts.push(`context ${typesPrefix}${policy.contextGoName}`);
  }
  return parts.join(", ");
}

/**
 * Renders doc and deprecation lines for a policy function.
 */
function renderDocLines(policy: PolicyModel): string[] {
  const lines: string[] = [];
  if (policy.doc !== undefined && policy.doc.trim().length > 0) {
    const first = policy.doc.split("\n")[0]?.trim() ?? "";
    lines.push(`// ${policy.goName} checks the ${policy.name} policy.`);
    if (first.length > 0) {
      lines.push(`// ${first}`);
    }
  } else {
    lines.push(`// ${policy.goName} checks the ${policy.name} policy.`);
  }
  if (policy.isDeprecated) {
    const message = policy.deprecationMessage ?? "This policy is deprecated.";
    lines.push("//", `// Deprecated: ${message}`);
  }
  return lines;
}

/**
 * Renders the policy catalog type, value and name list.
 */
function renderCatalog(
  policies: PolicyModel[],
  typesPrefix: string,
  _schema: IrSchema,
): string[] {
  const lines: string[] = [
    "// VDLPolicyCatalog catalogs all @policy-annotated types with their check functions.",
    "type VDLPolicyCatalog struct {",
  ];
  for (const policy of policies) {
    const params = renderCheckSignature(policy, typesPrefix);
    lines.push(
      `\t// ${policy.goName} is the metadata for the ${policy.name} policy.`,
    );
    lines.push(`\t${policy.goName} struct {`);
    lines.push("\t\t// Name is the name of this policy.");
    lines.push("\t\tName string");
    lines.push("\t\t// Check evaluates this policy.");
    lines.push(`\t\tCheck func(${params}) bool`);
    lines.push("\t}");
  }
  lines.push(
    "}",
    "",
    "// VDLPolicies indexes generated policies by type name.",
    "var VDLPolicies = VDLPolicyCatalog{",
  );
  for (const policy of policies) {
    const params = renderCheckSignature(policy, typesPrefix);
    lines.push(
      `\t// ${policy.goName} is the metadata for the ${policy.name} policy.`,
    );
    lines.push(`\t${policy.goName}: struct {`);
    lines.push("\t\t// Name is the name of this policy.");
    lines.push("\t\tName string");
    lines.push("\t\t// Check evaluates this policy.");
    lines.push(`\t\tCheck func(${params}) bool`);
    lines.push("\t}{");
    lines.push(`\t\tName: ${JSON.stringify(policy.name)},`);
    lines.push(`\t\tCheck: ${policy.goName},`);
    lines.push("\t},");
  }
  lines.push(
    "}",
    "",
    "// Names returns every policy name in sorted order.",
    "func (c VDLPolicyCatalog) Names() []string {",
  );
  if (policies.length === 0) {
    lines.push("\treturn nil");
  } else {
    const names = policies
      .map((policy) => JSON.stringify(policy.name))
      .join(", ");
    lines.push(`\treturn []string{${names}}`);
  }
  lines.push("}");
  return lines;
}

/**
 * Renders the parameter types for a catalog check field without names.
 */
function renderCheckSignature(
  policy: PolicyModel,
  typesPrefix: string,
): string {
  const parts = [`${typesPrefix}${policy.principalGoName}`];
  if (
    policy.resourceType !== undefined &&
    policy.resourceGoName !== undefined
  ) {
    parts.push(`${typesPrefix}${policy.resourceGoName}`);
  }
  if (policy.contextType !== undefined && policy.contextGoName !== undefined) {
    parts.push(`${typesPrefix}${policy.contextGoName}`);
  }
  return parts.join(", ");
}
